import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useDonors } from '../contexts/DonorContext';
import { useOffline } from '../contexts/OfflineContext';
import apiService from '../services/apiService';

const Dashboard = () => {
    const { donors, loading, error, agentAssignments } = useDonors();
    const { isOffline, pendingUploads } = useOffline();
    const [dashboardStats, setDashboardStats] = useState({
        pendingSheepCount: 0,
        pendingCowSharesCount: 0,
        pendingCowGroups: 0,
        remainingCowShares: 0,
        totalValue: 0
    });

    // Fetch dashboard stats directly from API for real-time data
    useEffect(() => {
        const fetchDashboardStats = async () => {
            try {
                // Get dashboard counts from API
                const counts = await apiService.getDashboardCounts();

                // Get all pending donations to calculate total value
                const pendingDonations = await apiService.getDonationsByStatus('pending');

                // Calculate total value of pending donations
                const totalValue = pendingDonations.reduce((sum, donation) => {
                    return sum + parseFloat(donation.price || 0);
                }, 0);

                setDashboardStats({
                    ...counts,
                    totalValue
                });
            } catch (error) {
                console.error('Error fetching dashboard stats:', error);
            }
        };

        fetchDashboardStats();
    }, []);

    // Count statistics from current state (fallback if API fails)
    const totalDonors = donors.length;
    const pendingDonors = donors.filter(d => d.status === 'pending');
    const totalPending = pendingDonors.length;
    const totalProcessing = donors.filter(d => d.status === 'sending').length;
    const totalCompleted = donors.filter(d => d.status === 'done').length;

    const pendingUploadsCount = pendingUploads.length;

    return (
        <div>
            <h1 className="text-2xl font-bold mb-6">Dashboard</h1>

            {/* Quick actions */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                <Link to="/register" className="bg-white rounded-lg shadow-sm p-6 flex items-center hover:shadow-md transition-shadow">
                    <div className="bg-green-100 p-3 rounded-full">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                        </svg>
                    </div>
                    <div className="ml-4">
                        <h2 className="text-lg font-medium">Register New Donor</h2>
                        <p className="text-gray-500">Add new donation for sheep or cow</p>
                    </div>
                </Link>

                <Link to="/donors" className="bg-white rounded-lg shadow-sm p-6 flex items-center hover:shadow-md transition-shadow">
                    <div className="bg-blue-100 p-3 rounded-full">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 10h16M4 14h16M4 18h16" />
                        </svg>
                    </div>
                    <div className="ml-4">
                        <h2 className="text-lg font-medium">View All Donors</h2>
                        <p className="text-gray-500">Manage and track donations</p>
                    </div>
                </Link>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                <div className="bg-white rounded-lg shadow-sm p-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm text-gray-500">Pending Donors</p>
                            <h3 className="text-3xl font-bold">{dashboardStats.pendingSheepCount + dashboardStats.pendingCowSharesCount || totalPending}</h3>
                        </div>
                        <div className="bg-blue-100 p-2 rounded-full">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4 flex space-x-3">
                        <div className="bg-yellow-50 px-2 py-1 rounded-full text-xs font-medium text-yellow-700">{totalPending} Pending</div>
                        <div className="bg-blue-50 px-2 py-1 rounded-full text-xs font-medium text-blue-700">{totalProcessing} Processing</div>
                        <div className="bg-green-50 px-2 py-1 rounded-full text-xs font-medium text-green-700">{totalCompleted} Completed</div>
                    </div>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm text-gray-500">Pending Value</p>
                            <h3 className="text-3xl font-bold">{dashboardStats.totalValue?.toLocaleString() || 0} DA</h3>
                        </div>
                        <div className="bg-green-100 p-2 rounded-full">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <div className="text-sm text-gray-500">From {dashboardStats.pendingSheepCount + dashboardStats.pendingCowSharesCount} pending donations</div>
                    </div>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm text-gray-500">Pending Sacrifices</p>
                            <h3 className="text-3xl font-bold">
                                {(dashboardStats.pendingSheepCount || 0) + (dashboardStats.pendingCowGroups || 0)}
                            </h3>
                        </div>
                        <div className="bg-yellow-100 p-2 rounded-full">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-yellow-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4 flex space-x-3">
                        <div className="bg-blue-50 px-2 py-1 rounded-full text-xs font-medium text-blue-700">
                            {dashboardStats.pendingSheepCount || 0} Sheep
                        </div>
                        <div className="bg-purple-50 px-2 py-1 rounded-full text-xs font-medium text-purple-700">
                            {dashboardStats.pendingCowGroups || 0} Cows
                            {dashboardStats.remainingCowShares > 0 &&
                                <span className="ml-1">+{dashboardStats.remainingCowShares}/7</span>}
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-lg shadow-sm p-6">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-sm text-gray-500">Agents</p>
                            <h3 className="text-3xl font-bold">{agentAssignments?.length || 0}</h3>
                        </div>
                        <div className="bg-purple-100 p-2 rounded-full">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-purple-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        {agentAssignments?.length > 0 ? (
                            <div className="text-sm text-gray-500">Working on {totalProcessing} donations</div>
                        ) : (
                            <div className="text-sm text-gray-500">No agents assigned yet</div>
                        )}
                    </div>
                </div>
            </div>

            {/* Agent list */}
            <h2 className="text-xl font-semibold mb-4">Agent Workspaces</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                {agentAssignments && agentAssignments.length > 0 ? (
                    agentAssignments.map(agent => {
                        // Calculate progress
                        const agentDonors = donors.filter(d => {
                            const assignedDonor = agent.donors?.includes(d.id);
                            const assignedCow = agent.cowGroups?.some(group => group.includes(d.id));
                            return assignedDonor || assignedCow;
                        });

                        const completed = agentDonors.filter(d => d.status === 'done').length;
                        const total = agentDonors.length;
                        const progress = total > 0 ? Math.round((completed / total) * 100) : 0;

                        return (
                            <Link to={`/agent/${agent.id}`} key={agent.id} className="bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow">
                                <div className="p-6">
                                    <h3 className="font-medium text-lg">{agent.name || agent.agent_name}</h3>
                                    <div className="mt-2 text-sm text-gray-500">
                                        <p>Assigned: {total} donors</p>
                                        <p>Completed: {completed} ({progress}%)</p>
                                    </div>
                                    <div className="mt-3 w-full bg-gray-200 rounded-full h-2.5">
                                        <div
                                            className="bg-green-600 h-2.5 rounded-full"
                                            style={{ width: `${progress}%` }}
                                        ></div>
                                    </div>
                                </div>
                            </Link>
                        );
                    })
                ) : (
                    <div className="col-span-full bg-white rounded-lg shadow-sm p-6 text-center">
                        <p className="text-gray-500">No agents assigned yet. Go to Donor List to split donations between agents.</p>
                        <Link to="/donors" className="mt-4 btn btn-primary inline-block">
                            Manage Donors
                        </Link>
                    </div>
                )}
            </div>

            {/* Offline status */}
            {isOffline && (
                <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-8">
                    <div className="flex items-center">
                        <div className="flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-yellow-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                            </svg>
                        </div>
                        <div className="ml-3">
                            <p className="text-sm text-yellow-700">
                                You're currently offline. Don't worry, all your work is saved locally and will sync once you're back online.
                            </p>
                            {pendingUploadsCount > 0 && (
                                <p className="mt-1 text-sm text-yellow-700">
                                    <strong>{pendingUploadsCount}</strong> pending uploads will be processed when connection is restored.
                                </p>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Dashboard;
